        by[aid]={"id":aid,"displayName":name,"category":category,"tags":[name.lower(),slug.replace('_',' ')],"model":{"sourceBlend":f"res://assets/material_flow/{slug}/source/{slug}.blend","deliveryGltf":f"res://assets/material_flow/{slug}/delivery/{slug}.glb","lodFiles":[],"collisionFile":f"res://assets/material_flow/{slug}/collision/{slug}_collision.glb","thumbnailFile":f"res://assets/material_flow/{slug}/thumbnail.png"},"bounds":{"widthM":bounds[0],"heightM":bounds[1],"depthM":bounds[2]},"connectors":[],"kinematics":[axis(a) for a in axes],"signals":[signal(s) for s in signals],"quality":{"status":"candidate","blindReviewId":None,"recognitionConfidence":None,"topologyReviewed":True,"materialReviewed":True,"scaleReviewed":True,"animationReviewed":False}}
